"""Demo 1 - Shortlex enumeration and discovery indices.
Every finite string over a finite alphabet has a unique finite index in the
shortlex order; this demo computes indices and verifies the round-trip
e_sl(idx(s)) == s, illustrating the Enumeration and Discovery-Index Theorems.
"""
from __future__ import annotations
from itertools import product
from typing import Iterator


def shortlex(alphabet: str) -> Iterator[str]:
    length = 0
    while True:
        for tup in product(alphabet, repeat=length):
            yield "".join(tup)
        length += 1


def shortlex_index(s: str, alphabet: str) -> int:
    k = len(alphabet)
    pos = {c: i for i, c in enumerate(alphabet)}
    shorter = sum(k ** j for j in range(len(s)))
    within = 0
    for c in s:
        within = within * k + pos[c]
    return shorter + within


if __name__ == "__main__":
    alphabet = "ab"
    for s in ["", "a", "b", "aa", "ab", "aba", "abba"]:
        print(f"idx({s!r}) = {shortlex_index(s, alphabet)}")
    ok = all(shortlex_index(s, alphabet) == n
             for n, s in zip(range(500), shortlex(alphabet)))
    print("round-trip on first 500 strings:", ok)

"""Demo 2 - Non-exhaustibility and density-zero growth.
For a toy theorem set (nonempty palindromes) with natural density zero, the
number of theorems discovered by budget N grows without bound while the
fraction |D(N)|/N tends to 0 - the two are independent (Remark 3.4).
"""
from __future__ import annotations
from itertools import product
from typing import Callable, Iterator


def shortlex(alphabet: str) -> Iterator[str]:
    length = 0
    while True:
        for tup in product(alphabet, repeat=length):
            yield "".join(tup)
        length += 1


def discover(alphabet: str, is_theorem: Callable[[str], bool],
             budget: int) -> int:
    return sum(1 for _, s in zip(range(budget), shortlex(alphabet))
               if is_theorem(s))


if __name__ == "__main__":
    alphabet = "ab"
    is_theorem = lambda s: len(s) >= 1 and s == s[::-1]
    print(f"{'N':>10}{'|D(N)|':>10}{'|D(N)|/N':>14}")
    for N in [10, 100, 1000, 10000, 100000, 1000000]:
        d = discover(alphabet, is_theorem, N)
        print(f"{N:>10}{d:>10}{d / N:>14.6f}")

