from __future__ import annotations
from itertools import product
from typing import Callable, Iterator


def shortlex(alphabet: str) -> Iterator[str]:
    length: int = 0
    while True:
        for tup in product(alphabet, repeat=length):
            yield "".join(tup)
        length += 1


def budgeted_discovery(alphabet: str,
                       is_theorem: Callable[[str], bool],
                       budget: int) -> list[tuple[int, str]]:
    """Run the shortlex search for `budget` steps, returning the
    (index, theorem) pairs discovered. Guarantees |result| <= budget.
    """
    out: list[tuple[int, str]] = []
    for n, s in zip(range(budget), shortlex(alphabet)):
        if is_theorem(s):
            out.append((n, s))
    return out

