function INTERLEAVE(alphabet, is_thm1, is_thm2, budget):
    g1 <- SHORTLEX(alphabet); g2 <- SHORTLEX(alphabet)
    seen <- empty set; out <- empty list
    for step in 0..budget-1:
        (g, pred, tag) <- (g1,is_thm1,'S1') if step even else (g2,is_thm2,'S2')
        s <- next(g)
        if pred(s) and s not in seen:
            add s to seen; append (tag, s) to out
    return out
